questionvariables.text:
kgrp(n) := block([s, out, k], s: string(n), k: slength(s), if k < 5 then s else (out: "", while k > 3 do (out: sconcat("\\,", substring(s, k-2, k+1), out), k: k-3), sconcat(substring(s, 1, k+1), out)));
ksh(v) := block([c, w, f], c: floor(100*v+1/2), w: floor(c/100), f: c-100*w, if f = 0 then kgrp(w) else sconcat(kgrp(w), ".", if f < 10 then "0" else "", string(f)));
dd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else if integerp(1000*v) then dispdp(float(v),3) else dispdp(float(v),4);
ix: 1+rand(10);
/* Design: a claim to criticise: compare the total change with the sum of the yearly rates, for appreciation and depreciation. [kind, r, n]; key 3 on depreciation, 2 on appreciation. Source: adapted from SMP Book 3, revision page 139 question 3. */
L: [["dep",10,4],["app",8,5],["dep",15,4],["app",12,3],["dep",20,2],["app",6,4],["dep",12,5],["app",15,2],["dep",8,4],["app",10,6]];
E: L[ix];
kd: E[1]; r: E[2]; n: E[3];
nm: ["Achieng","Kiprono","Wanjiru","Omondi","Nekesa","Mutua","Chebet","Barasa","Njeri","Hassan"][ix];
dp: is(kd="dep");
mult: if dp then (1-r/100)^n else (1+r/100)^n;
mone: if dp then 1-r/100 else 1+r/100;
pc: abs(mult-1)*100;
nr: n*r;
ky: if dp then 3 else 2;
nky: 5-ky;
chg: if dp then "loss" else "gain";
/* diagnostics */
cl: nr;
remv: 100*mult;
one: r;
opt1: [[1, false, sconcat(nm, " is right: the yearly percentages add up.")], [2, is(ky=2), sconcat(nm, " is wrong: the actual ", chg, " is more than ", string(nr), "%.")], [3, is(ky=3), sconcat(nm, " is wrong: the actual ", chg, " is less than ", string(nr), "%.")], [4, false, "You cannot tell without knowing the price."]];
